"""Durable artifacts for media generated by the execution service.

Generators keep returning their bytes to the caller (and, where relevant,
writing them into a workspace). This helper adds a second, lifecycle-independent
copy to the storage service so the output survives a workspace deletion and
appears in the family's Artifact library.

Artifact creation is best-effort: a storage outage must never turn a finished
render into a failure. Callers include the returned artifact in their detail
when it succeeded and otherwise carry on with the original result.
"""
import base64
import json
import logging
import os
from typing import Any

from services.config import INTERNAL_SECRET, STORAGE_SVC_URL
from services.execution.http_client import request as http_request

log = logging.getLogger("execution.artifacts")

# The synthetic identities used by kiosk/voice callers are not people and have
# no Artifact library or quota of their own.
_NON_PERSONAL_OWNERS = {"", "anonymous", "household"}


def owner_of(user_context: Any) -> str:
    """Extract the Identity username from a UserContext or plain dict."""
    owner = (
        user_context.get("user")
        if isinstance(user_context, dict)
        else getattr(user_context, "user", None)
    )
    return str(owner or "").strip()


def artifact_name(path: str | None, fallback: str) -> str:
    """Use the generated file's basename, never a path from the caller."""
    name = os.path.basename((path or "").replace("\\", "/")).strip()
    return (name or fallback)[:255]


async def create_artifact(
    *,
    user_context: Any,
    kind: str,
    name: str,
    data: bytes,
    mime_type: str | None = None,
    workspace_id: str | None = None,
    generator: str | None = None,
    metadata: dict | None = None,
    timeout: int = 120,
) -> dict | None:
    """POST generated bytes to storage and return the artifact, or ``None``.

    Failures are logged and swallowed by design: the caller has already
    produced something useful and must not lose it because the library was
    unavailable.
    """
    owner = owner_of(user_context)
    if owner in _NON_PERSONAL_OWNERS:
        log.debug("Skipping artifact for non-personal identity %r", owner)
        return None
    if not data:
        log.warning("Skipping empty artifact %r", name)
        return None

    payload = {
        "name": artifact_name(name, "artifact"),
        "kind": kind,
        "mime_type": mime_type,
        "workspace_id": workspace_id,
        "generator": generator,
        "metadata": metadata or {},
        "content_b64": base64.b64encode(data).decode("ascii"),
    }
    try:
        resp = await http_request(
            "POST",
            f"{STORAGE_SVC_URL}/artifacts",
            json=payload,
            headers={"X-Internal-Secret": INTERNAL_SECRET, "X-User": owner},
            timeout=timeout,
        )
    except Exception as e:
        log.warning("Artifact upload failed for %s: %s", name, e)
        return None

    if resp.get("status_code") not in (200, 201):
        log.warning(
            "Artifact upload rejected for %s (status %s): %s",
            name,
            resp.get("status_code"),
            (resp.get("text") or "")[:300],
        )
        return None

    try:
        return json.loads(resp.get("text") or "{}")
    except (TypeError, ValueError):
        log.warning("Artifact upload returned an unreadable body for %s", name)
        return None
